def join_allocation_signature(typ):
    if (mode := exchange_type_mode(typ)) is not None:
        return mode, exchange_payload_type(mode), exchange_storage(typ)
    if (mode := option_type_mode(typ)) is not None:
        return mode, option_payload_type(mode), option_storage(typ)
    return owned_join_signature(typ)
